import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type {
  ProductionCostListingColumn,
  ProductionCostListingDetailRow,
  ProductionCostListingRow,
  ProductionCostListingRowTag,
} from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, monthStartEnd } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './BangKeSo4TapHopChiPhiSanXuatPage.module.css';

const TEST_ID = 'rpt-nkbk-chi-phi-sx';
const PAGE_ID = 'baocao-bang-ke-so-4-tap-hop-chi-phi-san-xuat';
const TITLE = 'Bảng kê số 4 - Tập hợp chi phí sản xuất';
const DEBIT_PREFIXES_LABEL = '154 · 621 · 622 · 627';

const PLACEHOLDER_COLUMNS: ProductionCostListingColumn[] = [
  { key: 'debitAccountCode', kind: 'fixed', headerVi: 'Tài khoản', headerEn: 'Account' },
  { key: 'debitAccountName', kind: 'fixed', headerVi: 'Tên tài khoản', headerEn: 'Account Name' },
  { key: 'rowTotal', kind: 'total', headerVi: 'Tổng cộng', headerEn: 'Total' },
];

const DRILL_HEADERS: { key: string; label: string; right?: boolean }[] = [
  { key: 'voucherDate', label: 'Ngày C.từ' },
  { key: 'documentType', label: 'Mã C.từ' },
  { key: 'voucherCode', label: 'Số Ct' },
  { key: 'debitCustomerCode', label: 'Mã khách' },
  { key: 'creditCustomerCode', label: 'Mã khách có' },
  { key: 'description', label: 'Diễn giải' },
  { key: 'debitAccountCode', label: 'Tk Nợ' },
  { key: 'creditAccountCode', label: 'TK có' },
  { key: 'amount', label: 'Phát sinh', right: true },
  { key: 'maVv', label: 'Vụ việc' },
  { key: 'maPhi', label: 'Phí' },
  { key: 'maSp', label: 'Sản phẩm' },
  { key: 'maHd', label: 'Hợp đồng' },
  { key: 'parentVoucherCode', label: 'Mã Ct0' },
];

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function mapRowTag(raw: ProductionCostListingRow['rowTag'], isBold?: boolean): ProductionCostListingRowTag {
  if (raw === 'GrandTotal') return 'GrandTotal';
  if (raw === 'Detail') return 'Detail';
  if (isBold) return 'GrandTotal';
  return 'Detail';
}

function normalizeItems(items: ProductionCostListingRow[]): ProductionCostListingRow[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isBold);
    return {
      ...r,
      rowTag,
      isBold: rowTag === 'GrandTotal' || Boolean(r.isBold),
      detailOk: rowTag === 'Detail' ? Boolean(r.detailOk ?? true) : false,
      debitAccountCode: r.debitAccountCode ?? null,
      debitAccountName: r.debitAccountName ?? null,
      creditBuckets: r.creditBuckets ?? {},
      rowTotal: Number(r.rowTotal ?? 0),
    };
  });
}

function creditCodeOf(col: ProductionCostListingColumn): string {
  if (col.creditAccountCode) return col.creditAccountCode;
  if (col.key?.startsWith('C')) return col.key.slice(1).replace(/_/g, '.');
  return '';
}

function isCreditCol(col: ProductionCostListingColumn): boolean {
  return col.kind === 'credit' || Boolean(col.creditAccountCode);
}

function isTotalCol(col: ProductionCostListingColumn): boolean {
  return col.kind === 'total' || col.key === 'rowTotal';
}

function isCodeCol(col: ProductionCostListingColumn): boolean {
  return col.key === 'debitAccountCode';
}

function isNameCol(col: ProductionCostListingColumn): boolean {
  return col.key === 'debitAccountName';
}

function mapDrillTag(raw: ProductionCostListingDetailRow['rowTag']): 'Total' | 'Detail' {
  if (raw === 'Total') return 'Total';
  return 'Detail';
}

type DrillParams = {
  fromDate: string;
  toDate: string;
  debitAccountCode: string;
};

const BangKeSo4TapHopChiPhiSanXuatPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const initial = monthStartEnd();

  const [fromDate, setFromDate] = useState(initial.fromDate);
  const [toDate, setToDate] = useState(initial.toDate);
  const [columns, setColumns] = useState<ProductionCostListingColumn[]>(PLACEHOLDER_COLUMNS);
  const [items, setItems] = useState<ProductionCostListingRow[]>([]);
  const [grandTotalAmount, setGrandTotalAmount] = useState<number | null>(null);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const [drillOpen, setDrillOpen] = useState(false);
  const [drillParams, setDrillParams] = useState<DrillParams | null>(null);
  const [drillItems, setDrillItems] = useState<ProductionCostListingDetailRow[]>([]);
  const [drillLoading, setDrillLoading] = useState(false);
  const { showTableLoading } = useCatalogTableBusy(loading);

  const displayColumns = hasViewed && columns.length > 0 ? columns : PLACEHOLDER_COLUMNS;

  const summaryGrandTotal = useMemo(() => {
    if (!hasViewed) return null;
    if (grandTotalAmount != null) return grandTotalAmount;
    const gt = items.find(r => mapRowTag(r.rowTag, r.isBold) === 'GrandTotal');
    return gt ? Number(gt.rowTotal ?? 0) : null;
  }, [hasViewed, items, grandTotalAmount]);

  const detailCount = useMemo(
    () => items.filter(r => mapRowTag(r.rowTag, r.isBold) === 'Detail').length,
    [items],
  );

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    if (!fromDate.trim() || !toDate.trim()) {
      setFilterError('Chọn khoảng ngày');
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return;
    }
    if (toDate < fromDate) {
      setFilterError('Đến ngày phải ≥ Từ ngày');
      dispatchAppToast(dispatch, { message: 'Đến ngày phải ≥ Từ ngày', type: 'error' });
      return;
    }

    setLoading(true);
    analyticsService
      .getProductionCostListing({
        fromDate: fromDate.trim(),
        toDate: toDate.trim(),
        pageSize: 0,
      })
      .then(report => {
        const nextCols =
          Array.isArray(report.columns) && report.columns.length > 0
            ? report.columns
            : PLACEHOLDER_COLUMNS;
        setColumns(nextCols);
        setItems(normalizeItems(report.items ?? []));
        setGrandTotalAmount(
          report.meta?.grandTotalAmount != null
            ? Number(report.meta.grandTotalAmount)
            : report.summary?.grandTotalAmount != null
              ? Number(report.summary.grandTotalAmount)
              : null,
        );
        setAppliedFrom(fromDate.trim());
        setAppliedTo(toDate.trim());
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được bảng kê số 4 - tập hợp chi phí sản xuất'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [dispatch, fromDate, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    const next = monthStartEnd();
    setFromDate(next.fromDate);
    setToDate(next.toDate);
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading || !appliedFrom || !appliedTo) return;
    const fileName = `bang-ke-so-4-tap-hop-chi-phi-san-xuat_${appliedFrom}_${appliedTo}.xlsx`;
    void exportExcel(
      '/accounting/production-cost-listing/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        pageSize: 0,
      },
      fileName,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedFrom, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  const openDrill = useCallback(
    (params: DrillParams) => {
      setDrillParams(params);
      setDrillOpen(true);
      setDrillLoading(true);
      setDrillItems([]);
      analyticsService
        .getProductionCostListingDetail({
          fromDate: params.fromDate,
          toDate: params.toDate,
          debitAccountCode: params.debitAccountCode,
          pageSize: 0,
        })
        .then(report => {
          setDrillItems(report.items ?? []);
        })
        .catch(err => {
          dispatchAppToast(dispatch, {
            message: getApiErrorMessage(err, 'Không tải được chi tiết bảng kê tập hợp chi phí sản xuất'),
            type: 'error',
          });
        })
        .finally(() => setDrillLoading(false));
    },
    [dispatch],
  );

  const closeDrill = useCallback(() => {
    setDrillOpen(false);
    setDrillParams(null);
    setDrillItems([]);
  }, []);

  const onCellDrill = useCallback(
    (row: ProductionCostListingRow) => {
      if (!hasViewed || !appliedFrom || !appliedTo) return;
      const tag = mapRowTag(row.rowTag, row.isBold);
      if (tag !== 'Detail' || !row.detailOk) return;
      const debit = (row.debitAccountCode ?? '').trim();
      if (!debit) return;
      openDrill({
        fromDate: appliedFrom,
        toDate: appliedTo,
        debitAccountCode: debit,
      });
    },
    [appliedFrom, appliedTo, hasViewed, openDrill],
  );

  const exportDisabled = !hasViewed || loading || !appliedFrom;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: exportDisabled,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [exportDisabled, handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle =
    hasViewed && appliedFrom && appliedTo
      ? `Từ: ${formatDate(appliedFrom)} đến ngày ${formatDate(appliedTo)} · Nợ: ${DEBIT_PREFIXES_LABEL}`
      : undefined;

  const drillTitle = drillParams
    ? `Chi tiết tập hợp chi phí SX (Nợ ${drillParams.debitAccountCode})`
    : 'Chi tiết tập hợp chi phí SX';

  const listBody = showTableLoading ? null : (
    <div className={erp.tableWrapper}>
      {subtitle ? (
        <div
          data-testid={`${TEST_ID}-subtitle`}
          className={reportStyles.subtitle}
          style={{ marginBottom: '0.5rem' }}
        >
          {subtitle}
        </div>
      ) : null}
      {!hasViewed ? (
        <div className={erp.empty} style={{ marginBottom: '0.5rem' }}>
          Chọn khoảng ngày và bấm Xem
        </div>
      ) : null}
      <div className={styles.gridScroll} data-testid={`${TEST_ID}-grid-scroll`}>
        <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
          <thead>
            <tr>
              {displayColumns.map(col => {
                const credit = isCreditCol(col);
                const total = isTotalCol(col);
                const code = creditCodeOf(col);
                return (
                  <th
                    key={col.key}
                    className={credit || total ? reportStyles.colRight : undefined}
                    data-testid={
                      credit && code ? `${TEST_ID}-col-credit-${code}` : undefined
                    }
                    data-credit-account={credit ? code : undefined}
                  >
                    {col.headerVi ?? col.key}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {!hasViewed
              ? null
              : items.map((row, index) => {
                  const tag = mapRowTag(row.rowTag, row.isBold);
                  const isGrand = tag === 'GrandTotal';
                  const canDrill = tag === 'Detail' && Boolean(row.detailOk);
                  return (
                    <tr
                      key={`${tag}|${row.debitAccountCode ?? ''}|${index}`}
                      className={isGrand ? styles.rowToneGrandTotal : styles.rowToneDetail}
                      data-testid={`${TEST_ID}-row-${index}`}
                      data-row-tag={tag}
                      data-debit-account={row.debitAccountCode ?? ''}
                      data-is-bold={isGrand || row.isBold ? '1' : '0'}
                      data-detail-ok={canDrill ? '1' : '0'}
                    >
                      {displayColumns.map(col => {
                        const credit = isCreditCol(col);
                        const total = isTotalCol(col);

                        if (isCodeCol(col)) {
                          return (
                            <td key={col.key}>
                              {isGrand ? '' : (row.debitAccountCode ?? '')}
                            </td>
                          );
                        }

                        if (isNameCol(col)) {
                          return (
                            <td key={col.key}>{row.debitAccountName ?? ''}</td>
                          );
                        }

                        if (credit) {
                          const code = creditCodeOf(col);
                          const amount = Number(row.creditBuckets?.[code] ?? 0);
                          return (
                            <td
                              key={col.key}
                              className={`${styles.cellMoney}${
                                canDrill ? ` ${styles.cellDrillable}` : ''
                              }`}
                              data-testid={`${TEST_ID}-cell-${index}-${col.key}`}
                              data-drillable={canDrill ? '1' : '0'}
                              title={canDrill ? 'Xem chi tiết chứng từ' : undefined}
                              onClick={canDrill ? () => onCellDrill(row) : undefined}
                            >
                              {formatVnd(amount)}
                            </td>
                          );
                        }

                        if (total) {
                          return (
                            <td
                              key={col.key}
                              className={`${styles.cellYellowTotal} ${styles.cellMoney}${
                                canDrill ? ` ${styles.cellDrillable}` : ''
                              }`}
                              data-testid={`${TEST_ID}-cell-${index}-rowTotal`}
                              data-drillable={canDrill ? '1' : '0'}
                              title={canDrill ? 'Xem chi tiết chứng từ' : undefined}
                              onClick={canDrill ? () => onCellDrill(row) : undefined}
                            >
                              {formatVnd(Number(row.rowTotal ?? 0))}
                            </td>
                          );
                        }

                        return <td key={col.key} />;
                      })}
                    </tr>
                  );
                })}
          </tbody>
        </table>
      </div>
      {hasViewed && detailCount === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  const footer =
    hasViewed && summaryGrandTotal !== null ? (
      <div className={styles.summaryBar} data-testid={`${TEST_ID}-summary`}>
        <span>Tổng cộng: {formatVnd(summaryGrandTotal)}</span>
      </div>
    ) : undefined;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-list' }}
        listTitle={TITLE}
        filterMaxWidthPx={1400}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        footer={footer}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <Input
                type="date"
                label="Từ ngày"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-from`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <Input
                type="date"
                label="Đến ngày"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-to`}
              />
            </div>
            <div
              className={styles.debitLockBadge}
              data-testid={`${TEST_ID}-field-debitPrefixes`}
            >
              Nợ: <strong>{DEBIT_PREFIXES_LABEL}</strong>
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
        modals={
          drillOpen ? (
            <div
              className={styles.drillOverlay}
              data-testid={`${TEST_ID}-drill-modal`}
              role="dialog"
              aria-modal="true"
              onClick={e => {
                if (e.target === e.currentTarget) closeDrill();
              }}
            >
              <div className={styles.drillModal}>
                <div className={styles.drillHeader}>
                  <h3 className={styles.drillTitle}>{drillTitle}</h3>
                  <Button
                    variant="secondary"
                    onClick={closeDrill}
                    data-testid={`${TEST_ID}-drill-close`}
                  >
                    Đóng
                  </Button>
                </div>
                {drillLoading ? (
                  <div>Đang tải...</div>
                ) : (
                  <>
                    <div className={styles.gridScroll}>
                      <table
                        className={reportStyles.table}
                        data-testid={`${TEST_ID}-drill-grid`}
                      >
                        <thead>
                          <tr>
                            {DRILL_HEADERS.map(h => (
                              <th
                                key={h.key}
                                className={h.right ? reportStyles.colRight : undefined}
                              >
                                {h.label}
                              </th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {drillItems.map((row, index) => {
                            const tag = mapDrillTag(row.rowTag);
                            const isTotal = tag === 'Total';
                            return (
                              <tr
                                key={`${tag}|${row.voucherCode ?? ''}|${index}`}
                                className={
                                  isTotal ? styles.rowToneDrillTotal : styles.rowToneDrillDetail
                                }
                                data-row-tag={tag}
                              >
                                <td>
                                  {!row.voucherDate ? '' : formatDate(row.voucherDate)}
                                </td>
                                <td>{isTotal ? '' : (row.documentType ?? '')}</td>
                                <td>{isTotal ? '' : (row.voucherCode ?? '')}</td>
                                <td>{isTotal ? '' : (row.debitCustomerCode ?? '')}</td>
                                <td>{isTotal ? '' : (row.creditCustomerCode ?? '')}</td>
                                <td>{row.description ?? ''}</td>
                                <td>{isTotal ? '' : (row.debitAccountCode ?? '')}</td>
                                <td>{isTotal ? '' : (row.creditAccountCode ?? '')}</td>
                                <td className={reportStyles.colRight}>
                                  {row.amount == null ? '' : formatVnd(Number(row.amount))}
                                </td>
                                <td>{isTotal ? '' : (row.maVv ?? '')}</td>
                                <td>{isTotal ? '' : (row.maPhi ?? '')}</td>
                                <td>{isTotal ? '' : (row.maSp ?? '')}</td>
                                <td>{isTotal ? '' : (row.maHd ?? '')}</td>
                                <td>{isTotal ? '' : (row.parentVoucherCode ?? '')}</td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                    {!drillLoading &&
                    drillItems.filter(r => mapDrillTag(r.rowTag) === 'Detail').length ===
                      0 ? (
                      <div
                        className={styles.drillEmpty}
                        data-testid={`${TEST_ID}-drill-empty`}
                      >
                        Không có dữ liệu chi tiết
                      </div>
                    ) : null}
                  </>
                )}
              </div>
            </div>
          ) : undefined
        }
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default BangKeSo4TapHopChiPhiSanXuatPage;
